// anyTools script API. This file is generated by anyTools; edits are overwritten.
//
// Scripts run inside an async function: top-level `await` and `return` work.
// Declare what a script needs on a comment line at the top, e.g.
//   // @permissions fs:~/Documents shell http:api.example.com
// The first run asks you to approve; editing the script asks again.

interface AnyToolsContext {
  /** The app that was in front when the wheel opened. */
  app: { id: string; name: string; pid: number; title?: string | null } | null;
  /** Selected files in Finder / Explorer (absolute paths). */
  selection: string[];
  /** Selected text in the front app (only read when a wheel rule uses `selection: text`). */
  text: string | null;
  /** The file manager's current folder, or the parent of the first selected file. */
  cwd: string | null;
  platform: 'mac' | 'win' | 'other';
}

declare const context: AnyToolsContext;

declare const console: {
  log(...args: unknown[]): void;
  info(...args: unknown[]): void;
  warn(...args: unknown[]): void;
  error(...args: unknown[]): void;
};
declare const log: typeof console;

/** Blocks for up to 10 s (and never past the script's time limit). */
declare function sleep(ms: number): void;

declare const keys: {
  /** `"mod+shift+p"` — `mod` is ⌘ on macOS and Ctrl on Windows. */
  send(chord: string): void;
  /** Types text into the front app. */
  type(text: string): void;
  /** Pastes text into the front app (⌘V / Ctrl+V); the clipboard is left as it was. */
  paste(text: string): void;
};

declare const clipboard: {
  readText(): string | null;
  writeText(text: string): void;
  readFiles(): string[];
  writeFiles(paths: string[]): void;
};

declare const app: {
  /** Bundle id / exe name, app name, or path. */
  launch(target: string): void;
  /** Opens a file, folder or URL with its default app. */
  open(target: string): void;
  frontmost(): { id: string; name: string; pid: number; title?: string | null } | null;
};

declare const ui: {
  notify(message: unknown, title?: string): void;
  /** Modal OK / Cancel dialog; true when OK. */
  confirm(message: string, title?: string): boolean;
};

/** Needs `// @permissions fs` or `fs:<dir>`. Paths must be absolute. */
declare const fs: {
  read(path: string): string;
  write(path: string, text: string): void;
  append(path: string, text: string): void;
  exists(path: string): boolean;
  list(dir: string): string[];
  mkdir(path: string): void;
  /** Moves to the Trash / Recycle Bin. */
  trash(path: string): void;
};

/** Needs `// @permissions shell`. Runs via zsh on macOS, PowerShell on Windows. */
declare const shell: {
  exec(command: string, options?: { cwd?: string; timeout?: number }): { code: number; stdout: string; stderr: string };
};

/** Needs `// @permissions http` or `http:<host>`. */
declare const http: {
  fetch(
    url: string,
    init?: { method?: string; headers?: Record<string, string>; body?: string },
  ): { status: number; ok: boolean; text: string; json(): any };
};
